    "개인키를 확인할까요?": "查看您的私钥？",
    "화면을 볼 수 있는 사람은 개인키로 자산을 가져갈 수 있습니다. 혼자 있는 안전한 장소에서만 확인해 주세요.": "任何能看到你私钥的人都可以拿走你的资产。仅在安全、私密的地方查看。",
