    "개인키를 별도로 백업해 주세요": "保留单独的私钥备份",
    "PSL Wallet 사용자들에게…": "致 PSL 钱包用户...",
    "현재 지갑의 개인키는 암호화되어 이 브라우저 또는 PWA의 저장소에 보관됩니다. 방문 기록만 지우는 경우에는 보통 유지되지만, 쿠키 및 사이트 데이터 등 지갑이 저장된 데이터를 삭제하면 개인키도 삭제될 수 있습니다.": "您的私钥在此浏览器或 PWA 存储中加密。单独清除浏览历史记录通常会保留它，但删除 cookie 和网站数据也可能会删除您的私钥。",
    "‘개인키 기기에 백업하기’를 누르면 개인키를 암호화된 파일로 기기에 별도 저장합니다. 이 파일은 브라우저의 사이트 데이터를 삭제해도 남습니다. 새 지갑을 만들거나 다른 개인키를 추가할 때마다 각각 백업해 주세요.": "选择“将私钥备份到设备”以保存单独的加密文件。当浏览器站点数据被清除时，该文件仍然存在。单独备份每个新的或导入的钱包。",
    "개인키를 별도로 보관하는 것이 중요합니다. 기기 분실이나 고장에 대비해 백업 파일의 사본을 다른 안전한 장소에도 보관하세요.": "保留单独的私钥备份至关重要。将另一个副本存放在安全的地方，以防您的设备丢失或损坏。",
    "다른 브라우저나 새 기기에서는 파일을 먼저 준비하고 ‘백업된 개인키 불러오기’를 누르세요. 백업 당시 비밀번호가 반드시 필요하며, 잊으면 이 파일로 복원할 수 없습니다. 지갑 잠금 비밀번호를 변경해도 파일의 비밀번호는 바뀌지 않습니다.": "要在其他浏览器或设备中恢复，请传输文件并选择“导入私钥备份”。您需要原来的备份密码；如果没有它，您将无法恢复该文件。更改钱包密码不会更改文件密码。",
    "백업용 비밀번호 (10자 이상, 12자 이상 권장)": "备份密码（10+ 个字符；建议 12+ 个字符）",
    "백업용 비밀번호 확인": "确认备份密码",
    "지갑을 사용하려면 저장한 파일을 다시 선택하고 비밀번호를 입력하여 백업을 확인해 주세요. 이미 백업한 파일도 확인할 수 있습니다.": "要使用您的钱包，请选择保存的文件并输入其密码以验证您的备份。您还可以验证现有的备份文件。",
