    "백업 비밀번호가 일치하지 않습니다.": "备份密码不匹配。",
    "파일 저장을 요청했습니다. 다운로드 또는 내 파일에서 저장 위치를 확인한 뒤, 아래 버튼으로 해당 파일을 다시 열어 주세요.": "请求下载文件。在“下载”或“我的文件”中找到该文件，然后使用下面的按钮重新打开它。",
    "백업 파일을 만들지 못했습니다. 비밀번호는 10자 이상이어야 합니다. 다시 시도해 주세요.": "无法创建备份。密码必须至少有 10 个字符。请再试一次。",
