    "기존 거래를 동일한 해시로 다시 전파하고 있습니다. 거래 해시: {0}": "使用相同的哈希重新广播现有事务：{0}",
    "기존 거래가 확인되었습니다. 거래 해시: {0}": "现有交易已确认。哈希值：{0}",
    "기존 거래를 다시 전파했지만 아직 확인 중입니다. 새 거래는 생성되지 않았습니다. 거래 해시: {0}": "现有交易重播；等待确认。没有创建新的交易。哈希值：{0}",
