    "{0}을 받을 수 있는 SASEUL 주소입니다.": "此 SASEUL 地址可以接收 {0}。",
    "이미 접수된 동일 전송이 확인되었습니다. 거래 해시: {0}": "之前提交的匹配转账已确认。哈希值：{0}",
    "동일한 전송이 이미 네트워크에 접수되어 확인 중입니다. 중복 전송을 막기 위해 다시 보내지 않았습니다. 거래 해시: {0}": "匹配的转账已在等待确认。为避免重复，不再发送。哈希值：{0}",
