    "Android 또는 브라우저가 앱 제거 시 사이트 저장소를 함께 삭제할 수도 있으므로, 앱을 제거하기 전에 개인키를 반드시 백업해 주세요.": "刪除應用程式時，Android 或您的瀏覽器可能會刪除網站資料。首先備份您的私鑰。",
