    "개인키를 확인할까요?": "查看您的私鑰？",
    "화면을 볼 수 있는 사람은 개인키로 자산을 가져갈 수 있습니다. 혼자 있는 안전한 장소에서만 확인해 주세요.": "任何能看到你私鑰的人都可以拿走你的資產。僅在安全、私密的地方查看。",
    "개인키 보기": "查看私鑰",
    "아래 개인키를 오프라인의 안전한 장소에 보관하세요.": "將此私鑰保存在安全的離線位置。",
    "개인키를 별도로 백업해 주세요": "保留單獨的私鑰備份",
    "PSL Wallet 사용자들에게…": "致 PSL 錢包用戶...",
    "현재 지갑의 개인키는 암호화되어 이 브라우저 또는 PWA의 저장소에 보관됩니다. 방문 기록만 지우는 경우에는 보통 유지되지만, 쿠키 및 사이트 데이터 등 지갑이 저장된 데이터를 삭제하면 개인키도 삭제될 수 있습니다.": "您的私鑰在此瀏覽器或 PWA 儲存體中加密。單獨清除瀏覽歷史記錄通常會保留它，但刪除 cookie 和網站資料也可能會刪除您的私鑰。",
    "‘개인키 기기에 백업하기’를 누르면 개인키를 암호화된 파일로 기기에 별도 저장합니다. 이 파일은 브라우저의 사이트 데이터를 삭제해도 남습니다. 새 지갑을 만들거나 다른 개인키를 추가할 때마다 각각 백업해 주세요.": "選擇“將私鑰備份到裝置”以保存單獨的加密檔案。當瀏覽器網站資料被清除時，該檔案仍然存在。單獨備份每個新的或導入的錢包。",
    "개인키를 별도로 보관하는 것이 중요합니다. 기기 분실이나 고장에 대비해 백업 파일의 사본을 다른 안전한 장소에도 보관하세요.": "保留單獨的私鑰備份至關重要。將另一個副本存放在安全的地方，以防您的設備遺失或損壞。",
    "다른 브라우저나 새 기기에서는 파일을 먼저 준비하고 ‘백업된 개인키 불러오기’를 누르세요. 백업 당시 비밀번호가 반드시 필요하며, 잊으면 이 파일로 복원할 수 없습니다. 지갑 잠금 비밀번호를 변경해도 파일의 비밀번호는 바뀌지 않습니다.": "若要在其他瀏覽器或裝置中恢復，請傳輸檔案並選擇「匯入私鑰備份」。您需要原始的備份密碼；如果沒有它，您將無法還原該檔案。更改錢包密碼不會更改檔案密碼。",
    "백업용 비밀번호 (10자 이상, 12자 이상 권장)": "備份密碼（10+ 個字元；建議 12+ 個字元）",
    "백업용 비밀번호 확인": "確認備份密碼",
    "지갑을 사용하려면 저장한 파일을 다시 선택하고 비밀번호를 입력하여 백업을 확인해 주세요. 이미 백업한 파일도 확인할 수 있습니다.": "要使用您的錢包，請選擇已儲存的檔案並輸入其密碼以驗證您的備份。您也可以驗證現有的備份檔案。",
