    "비밀번호가 올바르지 않거나 지갑 데이터가 손상되었습니다.": "密碼錯誤或錢包資料損壞。",
    "먼저 지갑 잠금을 해제해 주세요.": "先解鎖你的錢包。",
    "지갑 이름은 24자 이하로 입력해 주세요.": "錢包名稱不得超過 24 個字元。",
