    "설정을 저장했습니다.": "設定已儲存。",
    "이 기기에서 모든 지갑을 삭제할까요?": "要刪除該裝置上的所有錢包嗎？",
    "백업하지 않은 지갑과 개인키는 복구할 수 없습니다.": "沒有備份的錢包和私鑰無法恢復。",
    "이 기기에서 지갑을 삭제했습니다.": "錢包資料已從此裝置中刪除。",
    "수수료를 제외한 전송 가능 SL이 없습니다.": "付費後無法發送 SL。",
    "SL 최대 전송 금액을 계산하지 못했습니다.": "無法計算最大 SL 轉帳金額。",
