    "PSL 송금 수량 확인": "查看PSL轉帳金額",
    "받는 주소가 올바르지 않습니다.": "收件者地址無效。",
    "내 주소로는 전송할 수 없습니다.": "您無法發送至您自己的地址。",
    "0보다 큰 수량을 입력해 주세요.": "輸入大於零的金額。",
    "SL 수량과 네트워크 수수료를 합한 금액이 잔액을 초과합니다.": "SL 金額加上網路費用超過您的餘額。",
    "기존 지갑을 보호하기 위해 먼저 잠금을 해제한 후 백업을 불러와 주세요.": "在導入備份之前解鎖現有錢包以保護其資料。",
    "백업 비밀번호가 일치하지 않습니다.": "備份密碼不符。",
