    "암호화된 개인키가 브라우저 저장소에 남아 있으면 나중에 Wallet을 다시 설치한 뒤 기존 잠금 해제 비밀번호로 지갑을 사용할 수 있습니다.": "Nếu khóa mã hóa của bạn vẫn còn trong bộ nhớ trình duyệt, bạn có thể cài đặt lại Wallet và mở khóa bằng mật khẩu hiện có của mình.",
