    "새 개인키가 이 기기에서 안전하게 생성되고 현재 비밀번호로 암호화됩니다. 생성 후 개인키를 반드시 백업해 주세요.": "Khóa riêng mới sẽ được tạo an toàn trên thiết bị này và được mã hóa bằng mật khẩu hiện tại của bạn. Sao lưu nó sau khi tạo.",
