    "화면을 볼 수 있는 사람은 개인키로 자산을 가져갈 수 있습니다. 혼자 있는 안전한 장소에서만 확인해 주세요.": "Bất cứ ai có thể nhìn thấy khóa riêng của bạn đều có thể lấy tài sản của bạn. Chỉ xem nó ở một nơi an toàn, riêng tư.",
    "개인키 보기": "Xem khóa riêng",
    "아래 개인키를 오프라인의 안전한 장소에 보관하세요.": "Giữ khóa riêng này ở một vị trí ngoại tuyến an toàn.",
    "개인키를 별도로 백업해 주세요": "Giữ một bản sao lưu khóa riêng",
    "PSL Wallet 사용자들에게…": "Gửi tới người dùng Ví PSL…",
    "현재 지갑의 개인키는 암호화되어 이 브라우저 또는 PWA의 저장소에 보관됩니다. 방문 기록만 지우는 경우에는 보통 유지되지만, 쿠키 및 사이트 데이터 등 지갑이 저장된 데이터를 삭제하면 개인키도 삭제될 수 있습니다.": "Khóa riêng của bạn được mã hóa trong trình duyệt này hoặc bộ lưu trữ PWA. Chỉ xóa lịch sử duyệt web thường giữ lại khóa đó nhưng việc xóa cookie và dữ liệu trang web cũng có thể xóa khóa riêng tư của bạn.",
    "‘개인키 기기에 백업하기’를 누르면 개인키를 암호화된 파일로 기기에 별도 저장합니다. 이 파일은 브라우저의 사이트 데이터를 삭제해도 남습니다. 새 지갑을 만들거나 다른 개인키를 추가할 때마다 각각 백업해 주세요.": "Chọn “Sao lưu khóa riêng vào thiết bị” để lưu một tệp được mã hóa riêng. Tệp này vẫn còn khi dữ liệu trang web của trình duyệt bị xóa. Sao lưu riêng từng ví mới hoặc đã nhập.",
    "개인키를 별도로 보관하는 것이 중요합니다. 기기 분실이나 고장에 대비해 백업 파일의 사본을 다른 안전한 장소에도 보관하세요.": "Giữ một bản sao lưu khóa riêng riêng biệt là điều cần thiết. Lưu trữ một bản sao khác ở nơi an toàn trong trường hợp thiết bị của bạn bị mất hoặc bị hỏng.",
    "다른 브라우저나 새 기기에서는 파일을 먼저 준비하고 ‘백업된 개인키 불러오기’를 누르세요. 백업 당시 비밀번호가 반드시 필요하며, 잊으면 이 파일로 복원할 수 없습니다. 지갑 잠금 비밀번호를 변경해도 파일의 비밀번호는 바뀌지 않습니다.": "Để khôi phục trong trình duyệt hoặc thiết bị khác, hãy chuyển tệp và chọn “Nhập bản sao lưu khóa riêng”. Bạn cần mật khẩu dự phòng ban đầu; không có nó, bạn không thể khôi phục tập tin này. Thay đổi mật khẩu ví của bạn không thay đổi mật khẩu tập tin.",
    "백업용 비밀번호 (10자 이상, 12자 이상 권장)": "Mật khẩu sao lưu (10 ký tự trở lên; khuyến nghị 12 ký tự trở lên)",
    "백업용 비밀번호 확인": "Xác nhận mật khẩu dự phòng",
    "지갑을 사용하려면 저장한 파일을 다시 선택하고 비밀번호를 입력하여 백업을 확인해 주세요. 이미 백업한 파일도 확인할 수 있습니다.": "Để sử dụng ví của bạn, hãy chọn tệp đã lưu và nhập mật khẩu của nó để xác minh bản sao lưu của bạn. Bạn cũng có thể xác minh tệp sao lưu hiện có.",
    "저장한 백업 파일 확인하기": "Xác minh tập tin sao lưu đã lưu",
