    "백업 파일을 만들지 못했습니다. 비밀번호는 10자 이상이어야 합니다. 다시 시도해 주세요.": "Không thể tạo bản sao lưu. Mật khẩu phải có ít nhất 10 ký tự. Vui lòng thử lại.",
