    "현재 지갑 {0}개의 이름과 개인키로 파일을 교체합니다.\n{1}\n앱에 없는 지갑은 백업에서도 제외됩니다. 저장할까요?": "Thay thế tệp bằng tên và khóa riêng cho {0} ví hiện tại.\n{1}\nVí vắng mặt trong ứng dụng sẽ bị xóa khỏi bản sao lưu. Cứu?",
