    "기존 거래를 동일한 해시로 다시 전파하고 있습니다. 거래 해시: {0}": "Phát lại giao dịch hiện có với cùng hàm băm: {0}",
    "기존 거래가 확인되었습니다. 거래 해시: {0}": "Giao dịch hiện tại đã được xác nhận. Băm: {0}",
    "기존 거래를 다시 전파했지만 아직 확인 중입니다. 새 거래는 생성되지 않았습니다. 거래 해시: {0}": "Phát lại giao dịch hiện tại; đang chờ xác nhận. Không có giao dịch mới nào được tạo. Băm: {0}",
    "기존 거래의 유효 시간이 지나 노드가 거절했습니다. 이 해시는 더 이상 다시 전파하거나 체결할 수 없습니다. 거래 해시: {0}": "Nút đã từ chối giao dịch đã hết hạn này. Nó không thể được phát sóng lại hoặc thực thi nữa. Băm: {0}",
    "{0} 기존 해시는 보존되며 새 거래는 생성되지 않았습니다. 거래 해시: {1}": "{0} Hàm băm hiện có được giữ nguyên; không có giao dịch mới nào được tạo ra. Băm: {1}",
