    "{0}을 받을 수 있는 SASEUL 주소입니다.": "Địa chỉ SASEUL này có thể nhận được {0}.",
    "이미 접수된 동일 전송이 확인되었습니다. 거래 해시: {0}": "Việc chuyển khoản phù hợp đã gửi trước đó đã được xác nhận. Băm: {0}",
    "동일한 전송이 이미 네트워크에 접수되어 확인 중입니다. 중복 전송을 막기 위해 다시 보내지 않았습니다. 거래 해시: {0}": "Một giao dịch chuyển tiền phù hợp đang chờ xác nhận. Nó không được gửi lại để tránh trùng lặp. Băm: {0}",
    "PSL 전송 수수료 {0}를 낼 SL 잔액이 부족합니다.": "SL không đủ để thanh toán phí chuyển PSL là {0}.",
    "{0} {1} 전송 요청을 처리하고 익스플로러에서 거래 해시를 확인하고 있습니다.": "Đang xử lý quá trình chuyển {0} {1} và kiểm tra hàm băm của nó trong Explorer.",
    "네트워크가 전송을 접수했지만 탐색기 반영을 기다리고 있습니다. 중복 전송하지 마세요. 거래 해시: {0}": "Mạng đã chấp nhận chuyển khoản; đang chờ xác nhận của nhà thám hiểm. Đừng gửi nó nữa. Băm: {0}",
    "{0} {1} 전송이 확인되었습니다. 거래 해시: {2}": "Đã xác nhận chuyển giao {0} {1}. Băm: {2}",
    "거래 유효 시간이 지나 노드가 거절했습니다. 이 거래는 체결되지 않으며 이력에서 새 거래를 작성할 수 있습니다. 거래 해시: {0}": "Nút từ chối giao dịch đã hết hạn. Nó không thể thực thi. Tạo một giao dịch mới từ lịch sử. Băm: {0}",
    "{0} 중복 전송을 피하려면 이력 또는 익스플로러를 먼저 확인해 주세요.": "{0} Trước tiên hãy kiểm tra lịch sử hoặc trình khám phá để tránh chuyển dữ liệu trùng lặp.",
    "잘못된 백업 파일입니다.": "Tệp sao lưu không hợp lệ.",
