    "백업 파일을 저장했습니다. 저장한 파일을 다시 선택하여 확인해 주세요.": "File cadangan telah disimpan. Pilih lagi file yang disimpan untuk memverifikasinya.",
    "파일 저장 창이 완료되었습니다. 선택한 위치의 백업 파일을 다시 열어 확인해 주세요.": "Dialog penyimpanan file telah selesai. Buka kembali cadangan di lokasi pilihan Anda untuk memverifikasinya.",
    "다운로드를 요청했습니다. 브라우저에서 저장을 완료한 뒤 저장한 파일을 다시 선택하여 확인해 주세요.": "Pengunduhan telah diminta. Selesaikan penyimpanan di browser Anda, lalu pilih file yang disimpan untuk memverifikasinya.",
    "백업용 비밀번호를 입력하고 ‘새 백업 파일 저장’을 누르세요. 저장 후 파일을 다시 선택하여 확인하면 백업한 지갑을 사용할 수 있습니다.": "Masukkan dan konfirmasi kata sandi cadangan, lalu pilih Simpan file cadangan baru. Buka kembali file yang disimpan untuk memverifikasinya dan mengaktifkan dompet yang dicadangkan.",
    "백업 파일 저장": "Simpan file cadangan",
    "파일 저장 후 저장한 백업 파일 확인하기를 눌러 주세요.": "Setelah menyimpan, pilih Verifikasi file cadangan yang disimpan.",
    "파일을 저장하지 못했습니다. 다시 시도해 주세요.": "Tidak dapat menyimpan file. Silakan coba lagi.",
    "백업 파일 저장을 눌러 파일을 저장한 뒤, 저장한 백업 파일 확인하기를 눌러 주세요.": "Pilih Simpan file cadangan, lalu pilih Verifikasi file cadangan yang disimpan.",
    "저장 위치": "Simpan lokasi",
    "저장된 지갑 이름": "Nama dompet di cadangan",
    "마지막으로 확인한 백업 파일의 정보입니다. 파일 이동·삭제 여부는 자동으로 확인할 수 없습니다.": "Ini adalah rincian file cadangan terakhir yang diverifikasi. Memindahkan atau menghapus file tidak dapat terdeteksi secara otomatis.",
    "브라우저에서 전체 폴더 경로를 제공하지 않습니다. 파일 저장 시 선택한 폴더 또는 다운로드 폴더를 확인해 주세요.": "Browser tidak menyediakan jalur folder lengkap. Periksa folder yang dipilih saat menyimpan file atau folder Unduhan Anda.",
    "기기에 개인키 백업 후 사용가능": "Tersedia setelah mencadangkan kunci pribadi di perangkat",
    "백업용 비밀번호를 입력하고 ‘새 백업 파일 저장 후 확인’을 누르세요. 저장 후 파일을 다시 선택하여 확인하면 백업한 지갑을 사용할 수 있습니다.": "Masukkan kata sandi cadangan dan pilih “Simpan dan verifikasi file cadangan baru”. Buka kembali file yang disimpan untuk memverifikasinya dan mengaktifkan dompet yang dicadangkan.",
    "새 백업 파일이 필요하면 백업용 비밀번호를 입력하고 ‘새 백업 파일 저장 후 확인’을 누르세요. ‘개인키 기기에 백업하기’를 누르면 저장한 파일을 선택하여 확인할 수 있습니다. 현재 등록된 모든 지갑의 이름과 개인키를 백업해 주세요.": "Untuk membuat cadangan, masukkan kata sandi cadangan dan pilih “Simpan dan verifikasi file cadangan baru”. Pilih “Cadangkan kunci pribadi ke perangkat” untuk memilih dan memverifikasi file yang disimpan. Cadangkan setiap nama dompet dan kunci pribadi saat ini.",
    "토큰 CID": "Token ID",
    "개인키 복사": "Salin kunci pribadi",
    "신뢰하는 HTTPS RPC만 사용하세요. 변경한 RPC는 자동 저장됩니다.": "Gunakan hanya titik akhir HTTPS RPC yang tepercaya. Perubahan RPC disimpan secara otomatis.",
    "기존 파일을 현재 지갑 목록으로 업데이트합니다. 지원하는 브라우저에서는 같은 파일에 저장하며, 미지원 환경에서는 새 파일을 저장합니다.": "Perbarui file dengan dompet Anda saat ini. Browser yang didukung menyimpan ke file yang sama; browser lain menyimpan file baru.",
    "기존 백업 비밀번호를 그대로 사용합니다. 파일의 목록을 현재 지갑의 이름과 개인키로 교체하므로 앱에서 삭제한 지갑은 백업에서도 제외됩니다.": "Kata sandi cadangan tetap sama. File tersebut diganti dengan nama dan kunci dompet saat ini, tidak termasuk dompet yang dihapus dari aplikasi.",
    "업데이트할 지갑 다시 확인": "Tinjau dompet lagi",
