    "마지막으로 확인한 파일 내용과 현재 지갑 목록이 일치합니다. 파일을 이동하거나 삭제했다면 다시 확인해 주세요.": "File terverifikasi terakhir cocok dengan dompet Anda saat ini. Verifikasi lagi apakah Anda memindahkan atau menghapus file.",
