    "기기에 백업된 개인키 업데이트 필요": "Perbarui cadangan kunci pribadi di perangkat",
    "개인키 기기에 백업 안됨": "Kunci pribadi tidak dicadangkan di perangkat",
    "해결하기": "Putuskan",
    "확인하기": "Lihat detailnya",
    "(양호O) 개인키 기기에 백업 완료": "(Bagus O) Kunci pribadi dicadangkan di perangkat",
    "(주의!) 기기에 백업된 개인키 업데이트 필요": "(Perhatian!) Perbarui cadangan kunci pribadi pada perangkat",
    "(경고!) 개인키 기기에 백업 안됨": "(Peringatan!) Kunci pribadi tidak dicadangkan di perangkat",
    "본문으로 건너뛰기": "Lewati ke konten",
    "기존 파일을 선택하면 그 안의 지갑을 보존하고 새 지갑을 추가할 수 있습니다. 지원하는 브라우저에서는 동의 후 같은 파일에 저장하며, 미지원 환경에서는 새 통합 파일을 저장합니다.": "Pilih cadangan yang ada untuk mempertahankan dompetnya dan menambahkan yang baru. Browser yang didukung dapat memperbarui file yang sama dengan persetujuan Anda. Browser lain menyimpan file gabungan baru.",
    "추가할 지갑 확인": "Tinjau dompet untuk ditambahkan",
    "추가할 지갑 다시 확인": "Tinjau dompet lagi",
    "기존 백업 비밀번호를 그대로 사용합니다. 기존 파일에만 있는 지갑도 보존하며 같은 개인키는 중복 추가하지 않습니다.": "Kata sandi cadangan Anda saat ini tetap sama. Dompet yang hanya ditemukan di file akan disimpan, dan kunci pribadi duplikat tidak ditambahkan dua kali.",
    "이 브라우저는 기존 파일 덮어쓰기를 지원하지 않습니다. 파일을 선택하면 기존 지갑과 새 지갑을 합친 새 통합 백업을 저장합니다.": "Browser ini tidak dapat menimpa file yang sudah ada. Pilih file untuk menyimpan cadangan gabungan baru yang berisi dompet lama dan baru.",
    "기존 백업 파일을 업데이트하고 저장 내용을 확인했습니다. 지갑을 사용할 수 있습니다.": "Cadangan yang ada telah diperbarui dan diverifikasi. Anda sekarang dapat menggunakan dompet Anda.",
    "새 통합 파일 저장을 요청했습니다. 기존 파일은 그대로입니다. 저장한 새 파일을 다시 열어 확인해 주세요.": "Unduhan cadangan gabungan baru telah diminta. File asli tidak berubah. Buka kembali file baru yang disimpan untuk memverifikasinya.",
    "‘개인키 기기에 백업하기’를 누르면 현재 등록된 모든 지갑의 개인키와 이름을 하나의 암호화 파일로 저장합니다. 지갑을 추가한 뒤 다시 백업하면 이전 지갑과 새 지갑이 함께 포함됩니다. 기존 파일이 자동으로 갱신되지는 않으므로 최신 파일을 별도로 저장하고 확인해 주세요.": "Pilih “Cadangkan kunci pribadi ke perangkat” untuk menyimpan semua dompet terdaftar dan namanya dalam satu file terenkripsi. Cadangkan lagi setelah menambahkan dompet untuk menyertakan dompet lama dan baru. File lama tidak diperbarui secara otomatis. Simpan dan verifikasi file terbaru.",
    "다른 브라우저나 새 기기에서 최신 파일을 준비하고 ‘백업된 개인키 불러오기’를 누르면 파일에 포함된 모든 지갑을 복원합니다. 백업 당시 비밀번호가 반드시 필요하며, 잊으면 이 파일로 복원할 수 없습니다. 지갑 잠금 비밀번호를 변경해도 파일의 비밀번호는 바뀌지 않습니다.": "Untuk memulihkan setiap dompet dalam file, transfer cadangan terbaru ke browser Anda atau perangkat baru dan pilih “Impor cadangan kunci pribadi”. Anda memerlukan kata sandi cadangan asli; tanpanya, Anda tidak dapat memulihkan file. Mengubah kata sandi dompet Anda tidak mengubah kata sandi file.",
    "저장한 파일을 다시 선택하고 비밀번호를 입력해야 백업 확인이 완료됩니다. 파일에 포함된 지갑만 사용이 허용되며, 백업하지 않은 지갑은 계속 잠겨 있습니다. 이 파일은 브라우저의 사이트 데이터를 삭제해도 남습니다.": "Pilih file yang disimpan dan masukkan kata sandinya untuk memverifikasi cadangan Anda. Hanya dompet yang termasuk dalam file tersebut yang tersedia; dompet tanpa cadangan terverifikasi tetap terkunci. File tersebut tetap ada ketika data situs browser dihapus.",
    "1MB 이하의 지갑 백업 파일을 선택해 주세요.": "Pilih file cadangan dompet yang tidak lebih besar dari 1 MB.",
