    "암호화된 개인키가 브라우저 저장소에 남아 있으면 나중에 Wallet을 다시 설치한 뒤 기존 잠금 해제 비밀번호로 지갑을 사용할 수 있습니다.": "Jika kunci terenkripsi Anda tetap berada di penyimpanan browser, Anda dapat menginstal ulang Wallet dan membuka kuncinya dengan kata sandi yang ada.",
    "사이트 저장소 삭제": "Hapus data situs",
    "암호화된 개인키도 함께 삭제됩니다. 개인키를 백업하지 않았다면 지갑을 복구할 수 없습니다.": "Kunci pribadi terenkripsi Anda juga akan dihapus. Tanpa cadangan kunci pribadi, Anda tidak dapat memulihkan dompet Anda.",
    "Android 또는 브라우저가 앱 제거 시 사이트 저장소를 함께 삭제할 수도 있으므로, 앱을 제거하기 전에 개인키를 반드시 백업해 주세요.": "Android atau browser Anda mungkin menghapus data situs saat menghapus aplikasi. Cadangkan kunci pribadi Anda terlebih dahulu.",
