    "변경": "Perubahan",
    "개인키를 확인할까요?": "Lihat kunci pribadi Anda?",
    "화면을 볼 수 있는 사람은 개인키로 자산을 가져갈 수 있습니다. 혼자 있는 안전한 장소에서만 확인해 주세요.": "Siapa pun yang dapat melihat kunci pribadi Anda dapat mengambil aset Anda. Lihat hanya di tempat yang aman dan pribadi.",
    "개인키 보기": "Lihat kunci pribadi",
    "아래 개인키를 오프라인의 안전한 장소에 보관하세요.": "Simpan kunci pribadi ini di lokasi offline yang aman.",
    "개인키를 별도로 백업해 주세요": "Simpan cadangan kunci pribadi secara terpisah",
    "PSL Wallet 사용자들에게…": "Untuk pengguna Dompet PSL…",
    "현재 지갑의 개인키는 암호화되어 이 브라우저 또는 PWA의 저장소에 보관됩니다. 방문 기록만 지우는 경우에는 보통 유지되지만, 쿠키 및 사이트 데이터 등 지갑이 저장된 데이터를 삭제하면 개인키도 삭제될 수 있습니다.": "Kunci pribadi Anda dienkripsi di browser atau penyimpanan PWA ini. Menghapus riwayat penjelajahan saja biasanya akan menyimpannya, namun menghapus cookie dan data situs juga dapat menghapus kunci pribadi Anda.",
    "‘개인키 기기에 백업하기’를 누르면 개인키를 암호화된 파일로 기기에 별도 저장합니다. 이 파일은 브라우저의 사이트 데이터를 삭제해도 남습니다. 새 지갑을 만들거나 다른 개인키를 추가할 때마다 각각 백업해 주세요.": "Pilih “Cadangkan kunci pribadi ke perangkat” untuk menyimpan file terenkripsi terpisah. File ini tetap ada ketika data situs browser dihapus. Cadangkan setiap dompet baru atau yang diimpor secara terpisah.",
    "개인키를 별도로 보관하는 것이 중요합니다. 기기 분실이나 고장에 대비해 백업 파일의 사본을 다른 안전한 장소에도 보관하세요.": "Menyimpan cadangan kunci pribadi secara terpisah sangatlah penting. Simpan salinan lainnya di tempat yang aman jika perangkat Anda hilang atau rusak.",
    "다른 브라우저나 새 기기에서는 파일을 먼저 준비하고 ‘백업된 개인키 불러오기’를 누르세요. 백업 당시 비밀번호가 반드시 필요하며, 잊으면 이 파일로 복원할 수 없습니다. 지갑 잠금 비밀번호를 변경해도 파일의 비밀번호는 바뀌지 않습니다.": "Untuk memulihkan di browser atau perangkat lain, transfer file dan pilih “Impor cadangan kunci pribadi”. Anda memerlukan kata sandi cadangan asli; tanpanya, Anda tidak dapat memulihkan file ini. Mengubah kata sandi dompet Anda tidak mengubah kata sandi file.",
    "백업용 비밀번호 (10자 이상, 12자 이상 권장)": "Kata sandi cadangan (10+ karakter; disarankan 12+)",
    "백업용 비밀번호 확인": "Konfirmasikan kata sandi cadangan",
    "지갑을 사용하려면 저장한 파일을 다시 선택하고 비밀번호를 입력하여 백업을 확인해 주세요. 이미 백업한 파일도 확인할 수 있습니다.": "Untuk menggunakan dompet Anda, pilih file yang disimpan dan masukkan kata sandinya untuk memverifikasi cadangan Anda. Anda juga dapat memverifikasi file cadangan yang ada.",
