    "암호화된 개인키가 브라우저 저장소에 남아 있으면 나중에 Wallet을 다시 설치한 뒤 기존 잠금 해제 비밀번호로 지갑을 사용할 수 있습니다.": "यदि आपकी एन्क्रिप्टेड कुंजी ब्राउज़र स्टोरेज में रहती है, तो आप वॉलेट को पुनः इंस्टॉल कर सकते हैं और इसे अपने मौजूदा पासवर्ड से अनलॉक कर सकते हैं।",
    "사이트 저장소 삭제": "साइट डेटा हटाएँ",
    "암호화된 개인키도 함께 삭제됩니다. 개인키를 백업하지 않았다면 지갑을 복구할 수 없습니다.": "आपकी एन्क्रिप्ट की गई निजी कुंजी भी हटा दी जाएगी. निजी कुंजी बैकअप के बिना, आप अपना वॉलेट पुनर्प्राप्त नहीं कर सकते।",
    "Android 또는 브라우저가 앱 제거 시 사이트 저장소를 함께 삭제할 수도 있으므로, 앱을 제거하기 전에 개인키를 반드시 백업해 주세요.": "ऐप हटाते समय एंड्रॉइड या आपका ब्राउज़र साइट डेटा हटा सकता है। पहले अपनी निजी कुंजी का बैकअप लें।",
