    "새 지갑 이름": "नये बटुए का नाम",
    "변경": "परिवर्तन",
    "개인키를 확인할까요?": "अपनी निजी कुंजी देखें?",
    "화면을 볼 수 있는 사람은 개인키로 자산을 가져갈 수 있습니다. 혼자 있는 안전한 장소에서만 확인해 주세요.": "जो कोई भी आपकी निजी कुंजी देख सकता है वह आपकी संपत्ति ले सकता है। इसे केवल सुरक्षित, निजी स्थान पर ही देखें।",
    "개인키 보기": "निजी कुंजी देखें",
    "아래 개인키를 오프라인의 안전한 장소에 보관하세요.": "इस निजी कुंजी को सुरक्षित ऑफ़लाइन स्थान पर रखें।",
    "개인키를 별도로 백업해 주세요": "एक अलग निजी कुंजी बैकअप रखें",
    "PSL Wallet 사용자들에게…": "पीएसएल वॉलेट उपयोगकर्ताओं के लिए…",
    "현재 지갑의 개인키는 암호화되어 이 브라우저 또는 PWA의 저장소에 보관됩니다. 방문 기록만 지우는 경우에는 보통 유지되지만, 쿠키 및 사이트 데이터 등 지갑이 저장된 데이터를 삭제하면 개인키도 삭제될 수 있습니다.": "आपकी निजी कुंजी इस ब्राउज़र या PWA संग्रहण में एन्क्रिप्ट की गई है। ब्राउज़िंग इतिहास को केवल साफ़ करने से ही यह आमतौर पर बना रहता है, लेकिन कुकीज़ और साइट डेटा को हटाने से आपकी निजी कुंजी भी हट सकती है।",
    "‘개인키 기기에 백업하기’를 누르면 개인키를 암호화된 파일로 기기에 별도 저장합니다. 이 파일은 브라우저의 사이트 데이터를 삭제해도 남습니다. 새 지갑을 만들거나 다른 개인키를 추가할 때마다 각각 백업해 주세요.": "एक अलग एन्क्रिप्टेड फ़ाइल को सहेजने के लिए \"डिवाइस पर निजी कुंजी का बैकअप लें\" चुनें। ब्राउज़र साइट डेटा साफ़ होने पर यह फ़ाइल बनी रहती है। प्रत्येक नए या आयातित वॉलेट का अलग से बैकअप लें।",
    "개인키를 별도로 보관하는 것이 중요합니다. 기기 분실이나 고장에 대비해 백업 파일의 사본을 다른 안전한 장소에도 보관하세요.": "एक अलग निजी कुंजी बैकअप रखना आवश्यक है। यदि आपका उपकरण खो जाए या क्षतिग्रस्त हो जाए तो दूसरी प्रति सुरक्षित स्थान पर रखें।",
    "다른 브라우저나 새 기기에서는 파일을 먼저 준비하고 ‘백업된 개인키 불러오기’를 누르세요. 백업 당시 비밀번호가 반드시 필요하며, 잊으면 이 파일로 복원할 수 없습니다. 지갑 잠금 비밀번호를 변경해도 파일의 비밀번호는 바뀌지 않습니다.": "किसी अन्य ब्राउज़र या डिवाइस में पुनर्स्थापित करने के लिए, फ़ाइल को स्थानांतरित करें और \"निजी कुंजी बैकअप आयात करें\" चुनें। आपको मूल बैकअप पासवर्ड की आवश्यकता है; इसके बिना, आप इस फ़ाइल को पुनर्स्थापित नहीं कर सकते. अपना वॉलेट पासवर्ड बदलने से फ़ाइल पासवर्ड नहीं बदलता है।",
    "백업용 비밀번호 (10자 이상, 12자 이상 권장)": "बैकअप पासवर्ड (10+ अक्षर; 12+ अनुशंसित)",
    "백업용 비밀번호 확인": "बैकअप पासवर्ड की पुष्टि करें",
    "지갑을 사용하려면 저장한 파일을 다시 선택하고 비밀번호를 입력하여 백업을 확인해 주세요. 이미 백업한 파일도 확인할 수 있습니다.": "अपने वॉलेट का उपयोग करने के लिए, सहेजी गई फ़ाइल का चयन करें और अपने बैकअप को सत्यापित करने के लिए उसका पासवर्ड दर्ज करें। आप किसी मौजूदा बैकअप फ़ाइल को भी सत्यापित कर सकते हैं।",
