    "이 기기에서 모든 지갑을 삭제할까요?": "इस डिवाइस से सभी वॉलेट हटाएं?",
    "백업하지 않은 지갑과 개인키는 복구할 수 없습니다.": "बैकअप के बिना वॉलेट और निजी कुंजियाँ पुनर्प्राप्त नहीं की जा सकतीं।",
    "이 기기에서 지갑을 삭제했습니다.": "इस डिवाइस से वॉलेट डेटा हटा दिया गया है.",
    "수수료를 제외한 전송 가능 SL이 없습니다.": "फीस के बाद भेजने के लिए कोई एसएल उपलब्ध नहीं है।",
    "SL 최대 전송 금액을 계산하지 못했습니다.": "अधिकतम एसएल स्थानांतरण राशि की गणना नहीं की जा सकी.",
    "PSL은 소수점 이하 단위로 전송할 수 없습니다. 최소 송금 가능 금액은 1 PSL입니다.": "पीएसएल स्थानांतरण में संपूर्ण इकाइयों का उपयोग होना चाहिए। न्यूनतम स्थानांतरण 1 पीएसएल है।",
    "PSL 송금 수량 확인": "पीएसएल हस्तांतरण राशि की जाँच करें",
    "받는 주소가 올바르지 않습니다.": "अमान्य प्राप्तकर्ता पता.",
    "내 주소로는 전송할 수 없습니다.": "आप अपने पते पर नहीं भेज सकते.",
    "0보다 큰 수량을 입력해 주세요.": "शून्य से अधिक राशि दर्ज करें.",
    "SL 수량과 네트워크 수수료를 합한 금액이 잔액을 초과합니다.": "एसएल राशि और नेटवर्क शुल्क आपकी शेष राशि से अधिक है।",
    "기존 지갑을 보호하기 위해 먼저 잠금을 해제한 후 백업을 불러와 주세요.": "अपने डेटा की सुरक्षा के लिए बैकअप आयात करने से पहले अपने मौजूदा वॉलेट को अनलॉक करें।",
    "백업 비밀번호가 일치하지 않습니다.": "बैकअप पासवर्ड मेल नहीं खाते.",
    "파일 저장을 요청했습니다. 다운로드 또는 내 파일에서 저장 위치를 확인한 뒤, 아래 버튼으로 해당 파일을 다시 열어 주세요.": "फ़ाइल डाउनलोड का अनुरोध किया गया. फ़ाइल को डाउनलोड या मेरी फ़ाइलें में ढूंढें, फिर नीचे दिए गए बटन का उपयोग करके इसे फिर से खोलें।",
    "백업 파일을 만들지 못했습니다. 비밀번호는 10자 이상이어야 합니다. 다시 시도해 주세요.": "बैकअप नहीं बनाया जा सका. पासवर्ड कम से कम 10 अक्षर का होना चाहिए. कृपया पुन: प्रयास करें।",
    "16KB 이하의 지갑 백업 파일을 선택해 주세요.": "एक वॉलेट बैकअप फ़ाइल चुनें जो 16 KB से बड़ी न हो।",
    "새 잠금 비밀번호를 10자 이상 입력하고 동일하게 확인해 주세요.": "कम से कम 10 अक्षरों का नया वॉलेट पासवर्ड दर्ज करें और पुष्टि करें।",
    "선택한 지갑의 백업 파일이 아닙니다.": "यह बैकअप किसी भिन्न वॉलेट का है.",
    "백업 확인을 완료했습니다. 지갑을 사용할 수 있습니다.": "बैकअप सत्यापित. अब आप अपने वॉलेट का उपयोग कर सकते हैं.",
    "이미 등록된 지갑의 백업을 확인했습니다.": "मौजूदा वॉलेट के लिए बैकअप सत्यापित।",
    "백업 파일에서 지갑을 복원했습니다.": "वॉलेट को बैकअप से पुनर्स्थापित किया गया।",
    "비밀번호가 잘못되었거나 파일이 손상되었거나 저장 공간이 부족합니다. 기존 지갑은 유지됩니다.": "गलत पासवर्ड, क्षतिग्रस्त फ़ाइल, या अपर्याप्त भंडारण। आपके मौजूदा बटुए सुरक्षित हैं.",
    "보안을 위해 기존 평문 키를 제거했습니다. 백업 키를 다시 가져와 주세요.": "सुरक्षा के लिए पुरानी अनएन्क्रिप्टेड कुंजी हटा दी गई थी। अपनी बैकअप कुंजी दोबारा आयात करें.",
    "언어 선택": "भाषा चुनें",
