    "기존 거래를 동일한 해시로 다시 전파하고 있습니다. 거래 해시: {0}": "मौजूदा लेनदेन को उसी हैश के साथ पुनः प्रसारित करना: {0}",
    "기존 거래가 확인되었습니다. 거래 해시: {0}": "मौजूदा लेनदेन की पुष्टि की गई. हैश: {0}",
    "기존 거래를 다시 전파했지만 아직 확인 중입니다. 새 거래는 생성되지 않았습니다. 거래 해시: {0}": "मौजूदा लेन-देन पुनः प्रसारण; पुष्टिकरण की प्रतीक्षा। कोई नया लेन-देन नहीं बनाया गया. हैश: {0}",
    "기존 거래의 유효 시간이 지나 노드가 거절했습니다. 이 해시는 더 이상 다시 전파하거나 체결할 수 없습니다. 거래 해시: {0}": "नोड ने इस समाप्त लेनदेन को अस्वीकार कर दिया। इसे अब दोबारा प्रसारित या क्रियान्वित नहीं किया जा सकता। हैश: {0}",
    "{0} 기존 해시는 보존되며 새 거래는 생성되지 않았습니다. 거래 해시: {1}": "{0} मौजूदा हैश संरक्षित है; कोई नया लेन-देन नहीं बनाया गया. हैश: {1}",
    "{0} 전송 만료됨": "{0} स्थानांतरण समाप्त हो गया",
