    "앱을 제거하기 전에 확인해 주세요": "Bago alisin ang app",
    "사이트 저장소 유지": "Panatilihin ang data ng site",
    "암호화된 개인키가 브라우저 저장소에 남아 있으면 나중에 Wallet을 다시 설치한 뒤 기존 잠금 해제 비밀번호로 지갑을 사용할 수 있습니다.": "Kung mananatili ang iyong naka-encrypt na key sa storage ng browser, maaari mong muling i-install ang Wallet at i-unlock ito gamit ang iyong umiiral na password.",
    "사이트 저장소 삭제": "Tanggalin ang data ng site",
    "암호화된 개인키도 함께 삭제됩니다. 개인키를 백업하지 않았다면 지갑을 복구할 수 없습니다.": "Ang iyong naka-encrypt na pribadong key ay tatanggalin din. Kung walang backup na pribadong key, hindi mo mababawi ang iyong wallet.",
    "Android 또는 브라우저가 앱 제거 시 사이트 저장소를 함께 삭제할 수도 있으므로, 앱을 제거하기 전에 개인키를 반드시 백업해 주세요.": "Maaaring tanggalin ng Android o ng iyong browser ang data ng site kapag inaalis ang app. I-back up muna ang iyong pribadong key.",
    "개인키 백업": "PRIBADONG KEY BACKUP",
