    "새 지갑을 생성하시겠습니까?": "Gumawa ng bagong wallet?",
    "새 개인키가 이 기기에서 안전하게 생성되고 현재 비밀번호로 암호화됩니다. 생성 후 개인키를 반드시 백업해 주세요.": "Ligtas na bubuo ng bagong pribadong key sa device na ito at ie-encrypt gamit ang iyong kasalukuyang password. I-back up ito pagkatapos ng paggawa.",
