    "확인을 위해 “삭제”를 입력해 주세요.": "I-type ang “DELETE” para kumpirmahin.",
    "삭제": "Tanggalin",
    "“삭제”를 정확히 입력해 주세요.": "I-type nang eksakto ang “DELETE”.",
    "지갑 이름 변경": "Palitan ang pangalan ng wallet",
    "새 지갑 이름": "Bagong pangalan ng wallet",
    "변경": "Baguhin",
    "개인키를 확인할까요?": "Tingnan ang iyong pribadong key?",
    "화면을 볼 수 있는 사람은 개인키로 자산을 가져갈 수 있습니다. 혼자 있는 안전한 장소에서만 확인해 주세요.": "Maaaring kunin ng sinumang makakakita sa iyong pribadong key ang iyong mga asset. Tingnan lamang ito sa isang ligtas at pribadong lugar.",
    "개인키 보기": "Tingnan ang pribadong key",
    "아래 개인키를 오프라인의 안전한 장소에 보관하세요.": "Panatilihin ang pribadong key na ito sa isang ligtas na offline na lokasyon.",
    "개인키를 별도로 백업해 주세요": "Panatilihin ang isang hiwalay na pribadong key backup",
    "PSL Wallet 사용자들에게…": "Sa mga gumagamit ng PSL Wallet…",
    "현재 지갑의 개인키는 암호화되어 이 브라우저 또는 PWA의 저장소에 보관됩니다. 방문 기록만 지우는 경우에는 보통 유지되지만, 쿠키 및 사이트 데이터 등 지갑이 저장된 데이터를 삭제하면 개인키도 삭제될 수 있습니다.": "Ang iyong pribadong key ay naka-encrypt sa browser na ito o imbakan ng PWA. Ang pag-clear sa kasaysayan ng pagba-browse lamang ay karaniwang nagpapanatili nito, ngunit ang pagtanggal ng cookies at data ng site ay maaari ring tanggalin ang iyong pribadong key.",
    "‘개인키 기기에 백업하기’를 누르면 개인키를 암호화된 파일로 기기에 별도 저장합니다. 이 파일은 브라우저의 사이트 데이터를 삭제해도 남습니다. 새 지갑을 만들거나 다른 개인키를 추가할 때마다 각각 백업해 주세요.": "Piliin ang “I-back up ang pribadong key sa device” para mag-save ng hiwalay na naka-encrypt na file. Nananatili ang file na ito kapag na-clear ang data ng site ng browser. I-back up ang bawat bago o na-import na wallet nang hiwalay.",
    "개인키를 별도로 보관하는 것이 중요합니다. 기기 분실이나 고장에 대비해 백업 파일의 사본을 다른 안전한 장소에도 보관하세요.": "Ang pagpapanatiling isang hiwalay na pribadong key backup ay mahalaga. Mag-imbak ng isa pang kopya sa isang ligtas na lugar kung sakaling mawala o masira ang iyong device.",
    "다른 브라우저나 새 기기에서는 파일을 먼저 준비하고 ‘백업된 개인키 불러오기’를 누르세요. 백업 당시 비밀번호가 반드시 필요하며, 잊으면 이 파일로 복원할 수 없습니다. 지갑 잠금 비밀번호를 변경해도 파일의 비밀번호는 바뀌지 않습니다.": "Para i-restore sa ibang browser o device, ilipat ang file at piliin ang “Import private key backup”. Kailangan mo ang orihinal na backup na password; kung wala ito, hindi mo maibabalik ang file na ito. Ang pagpapalit ng iyong password sa wallet ay hindi nagbabago sa password ng file.",
    "백업용 비밀번호 (10자 이상, 12자 이상 권장)": "Backup na password (10+ character; 12+ ang inirerekomenda)",
    "백업용 비밀번호 확인": "Kumpirmahin ang backup na password",
    "지갑을 사용하려면 저장한 파일을 다시 선택하고 비밀번호를 입력하여 백업을 확인해 주세요. 이미 백업한 파일도 확인할 수 있습니다.": "Para gamitin ang iyong wallet, piliin ang naka-save na file at ilagay ang password nito para i-verify ang iyong backup. Maaari mo ring i-verify ang isang umiiral nang backup na file.",
    "저장한 백업 파일 확인하기": "I-verify ang naka-save na backup na file",
