    "백업하지 않은 지갑과 개인키는 복구할 수 없습니다.": "Hindi na mababawi ang mga pitaka at pribadong key na walang backup.",
    "이 기기에서 지갑을 삭제했습니다.": "Ang data ng wallet ay tinanggal mula sa device na ito.",
    "수수료를 제외한 전송 가능 SL이 없습니다.": "Walang SL na magagamit na ipadala pagkatapos ng mga bayarin.",
    "SL 최대 전송 금액을 계산하지 못했습니다.": "Hindi makalkula ang maximum na halaga ng paglilipat ng SL.",
    "PSL은 소수점 이하 단위로 전송할 수 없습니다. 최소 송금 가능 금액은 1 PSL입니다.": "Ang mga paglilipat ng PSL ay dapat gumamit ng buong mga yunit. Ang minimum na paglipat ay 1 PSL.",
    "PSL 송금 수량 확인": "Suriin ang halaga ng paglipat ng PSL",
    "받는 주소가 올바르지 않습니다.": "Di-wastong address ng tatanggap.",
    "내 주소로는 전송할 수 없습니다.": "Hindi ka maaaring magpadala sa iyong sariling address.",
    "0보다 큰 수량을 입력해 주세요.": "Maglagay ng halagang mas malaki sa zero.",
    "SL 수량과 네트워크 수수료를 합한 금액이 잔액을 초과합니다.": "Ang halaga ng SL at bayad sa network ay lumampas sa iyong balanse.",
    "기존 지갑을 보호하기 위해 먼저 잠금을 해제한 후 백업을 불러와 주세요.": "I-unlock ang iyong umiiral na wallet bago mag-import ng backup upang protektahan ang data nito.",
    "백업 비밀번호가 일치하지 않습니다.": "Hindi tugma ang mga backup na password.",
    "파일 저장을 요청했습니다. 다운로드 또는 내 파일에서 저장 위치를 확인한 뒤, 아래 버튼으로 해당 파일을 다시 열어 주세요.": "Hiniling ang pag-download ng file. Hanapin ang file sa Downloads o My Files, pagkatapos ay muling buksan ito gamit ang button sa ibaba.",
    "백업 파일을 만들지 못했습니다. 비밀번호는 10자 이상이어야 합니다. 다시 시도해 주세요.": "Hindi makalikha ng backup. Dapat na hindi bababa sa 10 character ang password. Pakisubukang muli.",
    "16KB 이하의 지갑 백업 파일을 선택해 주세요.": "Pumili ng wallet backup file na hindi hihigit sa 16 KB.",
    "새 잠금 비밀번호를 10자 이상 입력하고 동일하게 확인해 주세요.": "Magpasok at kumpirmahin ang isang bagong password sa wallet na hindi bababa sa 10 character.",
    "선택한 지갑의 백업 파일이 아닙니다.": "Ang backup na ito ay kabilang sa ibang wallet.",
    "백업 확인을 완료했습니다. 지갑을 사용할 수 있습니다.": "Na-verify ang backup. Magagamit mo na ang iyong wallet.",
    "이미 등록된 지갑의 백업을 확인했습니다.": "Na-verify ang backup para sa isang umiiral nang wallet.",
    "백업 파일에서 지갑을 복원했습니다.": "Na-restore ang wallet mula sa backup.",
    "비밀번호가 잘못되었거나 파일이 손상되었거나 저장 공간이 부족합니다. 기존 지갑은 유지됩니다.": "Maling password, sirang file, o hindi sapat na storage. Ang iyong mga umiiral na wallet ay napanatili.",
    "보안을 위해 기존 평문 키를 제거했습니다. 백업 키를 다시 가져와 주세요.": "Ang lumang hindi naka-encrypt na key ay inalis para sa seguridad. I-import muli ang iyong backup na key.",
    "언어 선택": "Pumili ng wika",
    "사용할 언어를 선택해 주세요.": "Piliin ang iyong gustong wika.",
    "PSL지갑 개인키": "Pribadong key ng PSL Wallet",
    "오픈소스 · 개인키 직접 관리": "OPEN SOURCE · SELF CUSTODY",
    "다시 오신 것을 환영합니다": "WELCOME BACK",
