    "암호화된 개인키가 브라우저 저장소에 남아 있으면 나중에 Wallet을 다시 설치한 뒤 기존 잠금 해제 비밀번호로 지갑을 사용할 수 있습니다.": "暗号化されたキーがブラウザのストレージに残っている場合は、Wallet を再インストールし、既存のパスワードでロックを解除できます。",
