    "암호화된 개인키도 함께 삭제됩니다. 개인키를 백업하지 않았다면 지갑을 복구할 수 없습니다.": "暗号化された秘密キーも削除されます。秘密キーのバックアップがなければ、ウォレットを回復することはできません。",
    "Android 또는 브라우저가 앱 제거 시 사이트 저장소를 함께 삭제할 수도 있으므로, 앱을 제거하기 전에 개인키를 반드시 백업해 주세요.": "Android またはブラウザでは、アプリを削除するとサイト データが削除される場合があります。まず秘密キーをバックアップします。",
