    "변경": "変更",
    "개인키를 확인할까요?": "秘密キーを表示しますか?",
    "화면을 볼 수 있는 사람은 개인키로 자산을 가져갈 수 있습니다. 혼자 있는 안전한 장소에서만 확인해 주세요.": "あなたの秘密キーを見ることができる人は誰でもあなたの資産を盗むことができます。安全でプライベートな場所でのみ閲覧してください。",
    "개인키 보기": "秘密キーを表示する",
    "아래 개인키를 오프라인의 안전한 장소에 보관하세요.": "この秘密キーはオフラインの安全な場所に保管してください。",
    "개인키를 별도로 백업해 주세요": "秘密キーのバックアップを別に保管しておく",
    "PSL Wallet 사용자들에게…": "PSLウォレットをご利用の皆様へ…",
    "현재 지갑의 개인키는 암호화되어 이 브라우저 또는 PWA의 저장소에 보관됩니다. 방문 기록만 지우는 경우에는 보통 유지되지만, 쿠키 및 사이트 데이터 등 지갑이 저장된 데이터를 삭제하면 개인키도 삭제될 수 있습니다.": "秘密キーは、このブラウザまたは PWA ストレージで暗号化されます。通常、閲覧履歴を消去するだけでは履歴が残りますが、Cookie やサイト データを削除すると秘密キーも削除される可能性があります。",
    "‘개인키 기기에 백업하기’를 누르면 개인키를 암호화된 파일로 기기에 별도 저장합니다. 이 파일은 브라우저의 사이트 데이터를 삭제해도 남습니다. 새 지갑을 만들거나 다른 개인키를 추가할 때마다 각각 백업해 주세요.": "「秘密キーをデバイスにバックアップ」を選択して、別の暗号化ファイルを保存します。このファイルは、ブラウザのサイト データが消去されても残ります。新しいウォレットまたはインポートされたウォレットを個別にバックアップします。",
    "개인키를 별도로 보관하는 것이 중요합니다. 기기 분실이나 고장에 대비해 백업 파일의 사본을 다른 안전한 장소에도 보관하세요.": "個別の秘密キーのバックアップを保持することが不可欠です。デバイスの紛失または破損に備えて、別のコピーを安全な場所に保管してください。",
    "다른 브라우저나 새 기기에서는 파일을 먼저 준비하고 ‘백업된 개인키 불러오기’를 누르세요. 백업 당시 비밀번호가 반드시 필요하며, 잊으면 이 파일로 복원할 수 없습니다. 지갑 잠금 비밀번호를 변경해도 파일의 비밀번호는 바뀌지 않습니다.": "別のブラウザまたはデバイスで復元するには、ファイルを転送し、「秘密キーのバックアップをインポート」を選択します。元のバックアップ パスワードが必要です。これがないと、このファイルを復元できません。ウォレットのパスワードを変更しても、ファイルのパスワードは変更されません。",
    "백업용 비밀번호 (10자 이상, 12자 이상 권장)": "バックアップパスワード (10 文字以上、12 文字以上を推奨)",
    "백업용 비밀번호 확인": "バックアップパスワードの確認",
    "지갑을 사용하려면 저장한 파일을 다시 선택하고 비밀번호를 입력하여 백업을 확인해 주세요. 이미 백업한 파일도 확인할 수 있습니다.": "ウォレットを使用するには、保存したファイルを選択し、そのパスワードを入力してバックアップを確認します。既存のバックアップ ファイルを確認することもできます。",
    "저장한 백업 파일 확인하기": "保存されたバックアップファイルを確認する",
    "다른 지갑 선택": "別のウォレットを選択してください",
    "암호화된 백업 파일": "暗号化されたバックアップファイル",
    "백업 당시 비밀번호": "元のバックアップパスワード",
    "새 지갑 잠금 비밀번호 (10자 이상)": "新しいウォレットのパスワード (10 文字以上)",
    "새 지갑 잠금 비밀번호 확인": "新しいウォレットのパスワードを確認する",
    "이 브라우저는 안전한 암호화 저장소를 지원하지 않습니다.": "このブラウザは安全な暗号化ストレージをサポートしていません。",
    "지원하지 않는 지갑 데이터입니다.": "サポートされていないウォレット データです。",
    "지갑 데이터가 손상되었습니다.": "ウォレットのデータが破損しています。",
    "지갑 잠금을 먼저 해제해 주세요.": "まずウォレットのロックを解除してください。",
    "설정에서 토큰 CID 또는 올바른 발행자 주소를 입력해 주세요.": "設定にトークン CID または有効な発行者アドレスを入力します。",
    "처리 중…": "処理中…",
    "이 브라우저는 안전한 지갑 생성을 지원하지 않습니다.": "このブラウザは安全なウォレットの作成をサポートしていません。",
    "수량을 숫자로 입력해 주세요.": "数値を入力します。",
    "보유 수량이 부족합니다.": "バランスが不十分です。",
    "네트워크 요청에 실패했습니다.": "ネットワーク要求が失敗しました。",
    "토큰 잔액 형식이 올바르지 않습니다.": "トークン残高の形式が無効です。",
    "토큰 소수 자릿수가 설정과 일치하지 않습니다.": "トークンの小数点以下が設定と一致しません。",
    "지갑 이름을 입력해 주세요.": "ウォレット名を入力します。",
    "PSL 토큰 CID 또는 발행자 주소를 네트워크 설정에서 먼저 입력해 주세요.": "まず、ネットワーク設定で PSL トークンの CID または発行者のアドレスを入力します。",
    "지갑을 잠갔습니다.": "財布はロックされています。",
    "조회 중": "読み込み中",
    "선택": "選択",
    "이름 변경": "名前の変更",
    "마지막 지갑은 여기서 삭제할 수 없습니다. 설정의 “이 기기에서 지갑 삭제”를 이용해 주세요.": "ここでは最後のウォレットを削除することはできません。設定でウォレットの削除オプションを使用します。",
    "백업하지 않은 개인키는 복구할 수 없습니다.": "バックアップのない秘密キーは復元できません。",
    "연결 오류": "接続エラー",
    "온라인": "オンライン",
    "연결 안 됨": "切断されました",
    "오프라인": "オフライン",
    "거래 조회 노드에 연결할 수 없습니다.": "トランザクション検索ノードに接続できません。",
    "만료된 거래는 다시 체결되지 않습니다. 내용을 확인한 뒤 새 거래를 전송하세요.": "有効期限が切れたトランザクションを再度実行することはできません。新しいトランザクションを送信する前に詳細を確認してください。",
    "저장된 거래 정보가 올바르지 않아 다시 전파할 수 없습니다.": "保存されたトランザクションは無効であるため、再ブロードキャストできません。",
    "거래 확인": "取引を確認する",
    "다시 전파 중…": "再放送中…",
    "동일 해시 다시 전파": "同じハッシュを再ブロードキャストする",
    "전송 만료됨": "転送期限が切れました",
    "전송 확인 중": "転送保留中",
    "유효시간 만료 · 체결 불가": "期限切れ・実行できません",
    "네트워크 확인 대기 중": "ネットワークの確認を待っています",
    "새 거래 작성": "新しいトランザクションを作成する",
    "표시할 SL · PSL 송수신 이력이 없습니다.": "表示する SL または PSL 転送はありません。",
    "보냄 ↗": "送信済み ↗",
