    "수수료 계산 중…": "料金を計算中…",
    "수수료 확인 불가": "料金利用不可",
    "거래 이력을 불러오는 중입니다.": "取引履歴を読み込んでいます。",
    "거래 이력을 불러오지 못했습니다. 잠시 후 다시 시도해 주세요.": "取引履歴を読み込めませんでした。後でもう一度試してください。",
    "아래로 당겨 새로고침": "プルダウンして更新します",
    "놓아서 잔액 새로고침": "リリースして残高を更新する",
    "SL · PSL 잔액 갱신 중": "SL・PSLバランスのリフレッシュ",
    "잔액을 새로고침했습니다": "残高が更新されました",
    "개인키는 64자리 16진수여야 합니다.": "秘密キーには 64 個の 16 進文字が含まれている必要があります。",
    "QR 코드를 생성할 수 없습니다.": "QRコードを生成できません。",
    "주소를 복사했습니다.": "アドレスがコピーされました。",
    "복사할 수 없습니다. 주소를 길게 눌러 복사해 주세요.": "コピーできませんでした。アドレスを長押ししてコピーします。",
    "Safari에서 홈 화면 아이콘을 만들어 앱처럼 사용할 수 있습니다.": "Wallet をアプリとして使用するには、Safari にホーム画面アイコンを追加します。",
    "설치 방법 확인": "インストール手順",
    "브라우저 메뉴에서 앱 설치 또는 바로가기 만들기를 선택할 수 있습니다.": "ブラウザのメニューから「アプリのインストール」または「ショートカットの作成」を選択します。",
    "Wallet을 설치했습니다.": "ウォレットがインストールされました。",
    "브라우저 메뉴의 “앱 설치” 또는 “바로가기 만들기”를 선택하세요.": "ブラウザのメニューから「アプリのインストール」または「ショートカットの作成」を選択します。",
    "비밀번호가 일치하지 않습니다.": "パスワードが一致しません。",
    "비밀번호를 10자 이상 입력해 주세요.": "10文字以上のパスワードを入力してください。",
    "지갑을 만들었습니다. 지금 개인키를 백업하세요.": "ウォレットが作成されました。今すぐ秘密キーをバックアップしてください。",
    "지갑을 안전하게 가져왔습니다.": "ウォレットは安全にインポートされました。",
    "비밀번호가 올바르지 않거나 지갑 데이터가 손상되었습니다.": "パスワードが間違っているか、ウォレットデータが破損しています。",
    "먼저 지갑 잠금을 해제해 주세요.": "まずウォレットのロックを解除してください。",
    "지갑 이름은 24자 이하로 입력해 주세요.": "ウォレット名は 24 文字以下である必要があります。",
    "지갑 이름을 변경했습니다.": "ウォレットの名前が変更されました。",
    "이미 추가된 지갑입니다.": "このウォレットはすでに登録されています。",
    "배포 환경에서는 HTTPS RPC만 사용할 수 있습니다.": "デプロイされたアプリでは HTTPS RPC エンドポイントのみが許可されます。",
    "CID는 64자리 16진수여야 합니다.": "CID には 64 個の 16 進文字が含まれている必要があります。",
    "발행자 주소를 확인해 주세요.": "発行者のアドレスを確認してください。",
    "설정을 저장했습니다.": "設定が保存されました。",
    "이 기기에서 모든 지갑을 삭제할까요?": "このデバイスからすべてのウォレットを削除しますか?",
    "백업하지 않은 지갑과 개인키는 복구할 수 없습니다.": "バックアップのないウォレットと秘密鍵は復元できません。",
    "이 기기에서 지갑을 삭제했습니다.": "ウォレット データがこのデバイスから削除されました。",
    "수수료를 제외한 전송 가능 SL이 없습니다.": "料金を支払った後に送信できる SL はありません。",
    "SL 최대 전송 금액을 계산하지 못했습니다.": "SL転送量の最大値を計算できませんでした。",
    "PSL은 소수점 이하 단위로 전송할 수 없습니다. 최소 송금 가능 금액은 1 PSL입니다.": "PSL 転送ではユニット全体を使用する必要があります。最小転送量は 1 PSL です。",
    "PSL 송금 수량 확인": "PSL転送量を確認する",
    "받는 주소가 올바르지 않습니다.": "受信者のアドレスが無効です。",
    "내 주소로는 전송할 수 없습니다.": "自分の住所に送ることはできません。",
    "0보다 큰 수량을 입력해 주세요.": "ゼロより大きい金額を入力してください。",
    "SL 수량과 네트워크 수수료를 합한 금액이 잔액을 초과합니다.": "SL 金額とネットワーク料金が残高を超えています。",
    "기존 지갑을 보호하기 위해 먼저 잠금을 해제한 후 백업을 불러와 주세요.": "データを保護するために、バックアップをインポートする前に既存のウォレットのロックを解除してください。",
    "백업 비밀번호가 일치하지 않습니다.": "バックアップのパスワードが一致しません。",
    "파일 저장을 요청했습니다. 다운로드 또는 내 파일에서 저장 위치를 확인한 뒤, 아래 버튼으로 해당 파일을 다시 열어 주세요.": "ファイルのダウンロードが要求されました。 [ダウンロード] または [マイ ファイル] でファイルを見つけて、下のボタンを使用して再度開きます。",
    "백업 파일을 만들지 못했습니다. 비밀번호는 10자 이상이어야 합니다. 다시 시도해 주세요.": "バックアップを作成できませんでした。パスワードは 10 文字以上である必要があります。もう一度試してください。",
    "16KB 이하의 지갑 백업 파일을 선택해 주세요.": "16 KB 以下のウォレットのバックアップ ファイルを選択してください。",
    "새 잠금 비밀번호를 10자 이상 입력하고 동일하게 확인해 주세요.": "少なくとも 10 文字の新しいウォレット パスワードを入力して確認します。",
    "선택한 지갑의 백업 파일이 아닙니다.": "このバックアップは別のウォレットに属しています。",
    "백업 확인을 완료했습니다. 지갑을 사용할 수 있습니다.": "バックアップが確認されました。これでウォレットを使用できるようになります。",
    "이미 등록된 지갑의 백업을 확인했습니다.": "既存のウォレットのバックアップが確認されました。",
    "백업 파일에서 지갑을 복원했습니다.": "ウォレットがバックアップから復元されました。",
    "비밀번호가 잘못되었거나 파일이 손상되었거나 저장 공간이 부족합니다. 기존 지갑은 유지됩니다.": "パスワードが間違っているか、ファイルが破損しているか、ストレージが不十分です。既存のウォレットは保存されます。",
    "보안을 위해 기존 평문 키를 제거했습니다. 백업 키를 다시 가져와 주세요.": "古い暗号化されていないキーはセキュリティのために削除されました。バックアップキーを再度インポートします。",
