    "앱을 제거하기 전에 확인해 주세요": "Bevor Sie die App entfernen",
    "사이트 저장소 유지": "Bewahren Sie die Site-Daten auf",
    "암호화된 개인키가 브라우저 저장소에 남아 있으면 나중에 Wallet을 다시 설치한 뒤 기존 잠금 해제 비밀번호로 지갑을 사용할 수 있습니다.": "Wenn Ihr verschlüsselter Schlüssel im Browserspeicher verbleibt, können Sie Wallet neu installieren und mit Ihrem vorhandenen Passwort entsperren.",
    "사이트 저장소 삭제": "Site-Daten löschen",
    "암호화된 개인키도 함께 삭제됩니다. 개인키를 백업하지 않았다면 지갑을 복구할 수 없습니다.": "Ihr verschlüsselter privater Schlüssel wird ebenfalls gelöscht. Ohne ein Backup des privaten Schlüssels können Sie Ihr Wallet nicht wiederherstellen.",
    "Android 또는 브라우저가 앱 제거 시 사이트 저장소를 함께 삭제할 수도 있으므로, 앱을 제거하기 전에 개인키를 반드시 백업해 주세요.": "Android oder Ihr Browser löschen möglicherweise Websitedaten, wenn Sie die App entfernen. Sichern Sie zuerst Ihren privaten Schlüssel.",
    "개인키 백업": "PRIVATER SCHLÜSSEL-BACKUP",
    "지갑 데이터 삭제": "Wallet-Daten löschen",
    "개인키로 지갑 추가": "Wallet mit einem privaten Schlüssel hinzufügen",
    "예: 거래용 지갑": "z.B. Trading-Wallet",
