    "+ 새 지갑 생성": "+ Erstellen Sie eine neue Brieftasche",
    "새 지갑을 생성하시겠습니까?": "Eine neue Wallet erstellen?",
    "새 개인키가 이 기기에서 안전하게 생성되고 현재 비밀번호로 암호화됩니다. 생성 후 개인키를 반드시 백업해 주세요.": "Auf diesem Gerät wird sicher ein neuer privater Schlüssel generiert und mit Ihrem aktuellen Passwort verschlüsselt. Sichern Sie es nach der Erstellung.",
