    "확인": "Okay",
    "확인해 주세요": "Bitte prüfen",
    "지갑을 삭제할까요?": "Diese Brieftasche löschen?",
    "확인을 위해 “삭제”를 입력해 주세요.": "Geben Sie zur Bestätigung „DELETE“ ein.",
    "삭제": "Löschen",
    "“삭제”를 정확히 입력해 주세요.": "Bitte geben Sie genau „DELETE“ ein.",
    "지갑 이름 변경": "Wallet umbenennen",
    "새 지갑 이름": "Neuer Wallet-Name",
    "변경": "Veränderung",
    "개인키를 확인할까요?": "Sehen Sie sich Ihren privaten Schlüssel an?",
    "화면을 볼 수 있는 사람은 개인키로 자산을 가져갈 수 있습니다. 혼자 있는 안전한 장소에서만 확인해 주세요.": "Jeder, der Ihren privaten Schlüssel sehen kann, kann Ihr Vermögen nehmen. Sehen Sie es sich nur an einem sicheren, privaten Ort an.",
    "개인키 보기": "Privaten Schlüssel anzeigen",
    "아래 개인키를 오프라인의 안전한 장소에 보관하세요.": "Bewahren Sie diesen privaten Schlüssel an einem sicheren Offline-Ort auf.",
    "개인키를 별도로 백업해 주세요": "Bewahren Sie eine separate Sicherung des privaten Schlüssels auf",
    "PSL Wallet 사용자들에게…": "An PSL Wallet-Benutzer…",
    "현재 지갑의 개인키는 암호화되어 이 브라우저 또는 PWA의 저장소에 보관됩니다. 방문 기록만 지우는 경우에는 보통 유지되지만, 쿠키 및 사이트 데이터 등 지갑이 저장된 데이터를 삭제하면 개인키도 삭제될 수 있습니다.": "Ihr privater Schlüssel wird in diesem Browser oder PWA-Speicher verschlüsselt. Allein durch das Löschen des Browserverlaufs bleibt dieser normalerweise erhalten, aber durch das Löschen von Cookies und Website-Daten kann auch Ihr privater Schlüssel gelöscht werden.",
    "‘개인키 기기에 백업하기’를 누르면 개인키를 암호화된 파일로 기기에 별도 저장합니다. 이 파일은 브라우저의 사이트 데이터를 삭제해도 남습니다. 새 지갑을 만들거나 다른 개인키를 추가할 때마다 각각 백업해 주세요.": "Wählen Sie „Privaten Schlüssel auf Gerät sichern“, um eine separate verschlüsselte Datei zu speichern. Diese Datei bleibt bestehen, wenn die Browser-Site-Daten gelöscht werden. Sichern Sie jede neue oder importierte Wallet separat.",
    "개인키를 별도로 보관하는 것이 중요합니다. 기기 분실이나 고장에 대비해 백업 파일의 사본을 다른 안전한 장소에도 보관하세요.": "Es ist wichtig, ein separates Backup des privaten Schlüssels aufzubewahren. Bewahren Sie eine weitere Kopie an einem sicheren Ort auf, für den Fall, dass Ihr Gerät verloren geht oder beschädigt wird.",
    "다른 브라우저나 새 기기에서는 파일을 먼저 준비하고 ‘백업된 개인키 불러오기’를 누르세요. 백업 당시 비밀번호가 반드시 필요하며, 잊으면 이 파일로 복원할 수 없습니다. 지갑 잠금 비밀번호를 변경해도 파일의 비밀번호는 바뀌지 않습니다.": "Um die Wiederherstellung in einem anderen Browser oder Gerät durchzuführen, übertragen Sie die Datei und wählen Sie „Sicherung des privaten Schlüssels importieren“. Sie benötigen das Original-Backup-Passwort; Ohne sie können Sie diese Datei nicht wiederherstellen. Durch das Ändern Ihres Wallet-Passworts wird das Dateipasswort nicht geändert.",
    "백업용 비밀번호 (10자 이상, 12자 이상 권장)": "Backup-Passwort (10+ Zeichen; 12+ empfohlen)",
    "백업용 비밀번호 확인": "Bestätigen Sie das Backup-Passwort",
    "지갑을 사용하려면 저장한 파일을 다시 선택하고 비밀번호를 입력하여 백업을 확인해 주세요. 이미 백업한 파일도 확인할 수 있습니다.": "Um Ihr Wallet zu verwenden, wählen Sie die gespeicherte Datei aus und geben Sie deren Passwort ein, um Ihr Backup zu überprüfen. Sie können auch eine vorhandene Sicherungsdatei überprüfen.",
    "저장한 백업 파일 확인하기": "Überprüfen Sie die gespeicherte Sicherungsdatei",
    "다른 지갑 선택": "Wählen Sie ein anderes Wallet aus",
    "암호화된 백업 파일": "Verschlüsselte Sicherungsdatei",
    "백업 당시 비밀번호": "Ursprüngliches Backup-Passwort",
    "새 지갑 잠금 비밀번호 (10자 이상)": "Neues Wallet-Passwort (10+ Zeichen)",
    "새 지갑 잠금 비밀번호 확인": "Bestätigen Sie das neue Wallet-Passwort",
    "이 브라우저는 안전한 암호화 저장소를 지원하지 않습니다.": "Dieser Browser unterstützt keine sichere verschlüsselte Speicherung.",
